text:
{
  "title": "地方税法等の改正",
  "lead": {
    "es": "令和《れいわ》6年度《ねんど》の住民税《じゅうみんぜい》をへらすことなど、都道府県《とどうふけん》や市町村《しちょうそん》の税金《ぜいきん》（地方税《ちほうぜい》）のきまりを変《か》える法律《ほうりつ》です。",
    "hs": "令和6年度分の個人住民税の定額減税など、地方税（都道府県や市町村の税金）のしくみを改める法律です。",
    "std": "個人住民税の定額減税、法人事業税の外形標準課税の対象法人の見直しなど、地方税に関する改正を行う法律。",
    "univ": "個人住民税、法人事業税、固定資産税及び都市計画税、森林環境譲与税等について所要の改正を行う法律。"
  },
  "facts": [
    {
      "es": "令和《れいわ》6年度《ねんど》の個人《こじん》の住民税《じゅうみんぜい》を、決《き》まった額《がく》だけへらします（定額減税《ていがくげんぜい》）。",
      "hs": "令和6年度分の個人住民税について、定額減税（決まった額を差し引くこと）を行います。",
      "std": "令和6年度分の個人住民税について定額減税を実施する。",
      "univ": "令和6年度分の個人住民税について、定額減税を実施する。"
    },
    {
      "es": "会社《かいしゃ》にかかる税金《ぜいきん》（法人事業税《ほうじんじぎょうぜい》）で、会社《かいしゃ》の大《おお》きさなどで税金《ぜいきん》をかけるしくみ（外形標準課税《がいけいひょうじゅんかぜい》）の対象《たいしょう》になる会社《かいしゃ》が少《すく》なくなっているため、対象《たいしょう》を見直《みなお》します。",
      "hs": "減資（資本金を減らすこと）などで外形標準課税（事業の規模に応じて課税するしくみ）の対象となる法人が減っていることなどに対応するため、対象法人を見直します。",
      "std": "法人事業税について、減資等により外形標準課税の対象法人が減少していること等の課題に対応するため、適用対象法人を見直す。",
      "univ": "法人事業税について、減資等により外形標準課税の対象法人が減少していること等の課題に対応するため、その適用対象法人の見直しを行う。"
    },
    {
      "es": "土地《とち》などにかかる税金《ぜいきん》（固定資産税《こていしさんぜい》・都市計画税《としけいかくぜい》）は、令和《れいわ》6年度《ねんど》の見直《みなお》しにあたり、土地《とち》の税金《ぜいきん》が急《きゅう》に重《おも》くならないようにする今《いま》のしくみを続《つづ》けます。",
      "hs": "固定資産税と都市計画税は、令和6年度の評価｜替《が》え（土地などの価格の見直し）にあたり、今の土地の負担調整｜措置《そち》（税負担が急に増えないようにするしくみ）などを続けます。",
      "std": "固定資産税・都市計画税について、令和6年度の評価替えに当たり、土地に係る現行の負担調整措置等を継続する。",
      "univ": "固定資産税及び都市計画税について、令和6年度の評価替えに当たり、現行の土地に係る負担調整措置等を継続する。"
    },
    {
      "es": "森林《しんりん》を守《まも》るために国《くに》から市町村《しちょうそん》などに分《わ》けるお金《かね》（森林環境譲与税《しんりんかんきょうじょうよぜい》）の、分《わ》け方《かた》の基準《きじゅん》を見直《みなお》します。",
      "hs": "森林｜環境《かんきょう》｜譲与《じょうよ》税（森林整備のため国から自治体に配る税）の譲与《じょうよ》基準（配り方の基準）を見直します。",
      "std": "森林環境譲与税の譲与基準を見直す。",
      "univ": "森林環境譲与税について、譲与基準の見直しを行う。"
    },
    {
      "es": "税金《ぜいきん》を軽《かる》くする特別《とくべつ》なしくみなどを整理《せいり》します。この法律《ほうりつ》は、一部《いちぶ》をのぞき令和《れいわ》6年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。",
      "hs": "税負担軽減｜措置《そち》などの整理合理化を行います。一部を除き、令和6年4月1日から施行《しこう》します。",
      "std": "税負担軽減措置等の整理合理化等を行う。一部を除き令和6年4月1日から施行する。",
      "univ": "税負担軽減措置等の整理合理化等を行う。この法律は、一部を除き、令和6年4月1日から施行する。"
    }
  ]
}
